create or replace function crm_records.page(p_actor uuid,p_entity text,p_limit integer default 25,p_offset integer default 0,p_search text default '',p_pipeline text default '') returns jsonb language plpgsql security definer set search_path=pg_catalog,public,crm_records as $$
declare rows jsonb;label text;filter text;
begin
 perform crm_records.authorize(p_actor);
 if p_entity is null or p_entity not in ('contacts','pipelines','stages','deals','projects','activities') or p_limit is null or p_limit not between 1 and 100 or p_offset is null or p_offset<0 or p_search is null or length(p_search)>200 or p_pipeline is null then raise exception 'Consulta inválida.';end if;
 label:=case when p_entity in ('deals','activities') then 'title' else 'name' end;
 filter:=case when p_entity in ('stages','deals') then ' and ($4='''' or pipeline_id=$4)' else '' end;
 execute format('select coalesce(jsonb_agg(to_jsonb(r)),''[]''::jsonb) from (select * from crm_records.%I where strpos(lower(%I),lower($1))>0 %s order by id limit $2 offset $3) r',p_entity,label,filter) into rows using p_search,p_limit+1,p_offset,p_pipeline;
 return jsonb_build_object('rows',case when jsonb_array_length(rows)>p_limit then rows-(jsonb_array_length(rows)-1) else rows end,'hasMore',jsonb_array_length(rows)>p_limit);
end $$;

create or replace function public.crm_records_history(p_actor uuid,p_entity text,p_id text,p_limit integer default 25,p_before bigint default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,crm_records as $$
declare events jsonb;
begin
 perform crm_records.authorize(p_actor);
 if p_entity is null or p_entity not in ('contacts','pipelines','stages','deals','projects','activities') or coalesce(p_id,'') !~ '^[A-Za-z0-9_-]{1,100}$' or p_limit is null or p_limit not between 1 and 100 then raise exception 'Consulta inválida.';end if;
 select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) into events from (select * from crm_records.history where (entity=p_entity or (p_entity='deals' and entity='deal')) and entity_id=p_id and (p_before is null or id<p_before) order by id desc limit p_limit) r;
 return events;
end $$;

create or replace function public.crm_records_get(p_actor uuid,p_entity text,p_id text) returns jsonb language plpgsql security definer set search_path=pg_catalog,crm_records as $$
declare record jsonb;
begin
 perform crm_records.authorize(p_actor);
 if p_entity is null or p_entity not in ('contacts','pipelines','stages','deals','projects','activities') or coalesce(p_id,'') !~ '^[A-Za-z0-9_-]{1,100}$' then raise exception 'Consulta inválida.';end if;
 execute format('select to_jsonb(r) from crm_records.%I r where id=$1',p_entity) into record using p_id;
 return record;
end $$;
